from pathlib import Path
import html

root=Path(__file__).parent
photos={
'hero':'https://images.unsplash.com/photo-1664436341001-b02974ae7524?auto=format&fit=crop&w=2400&q=85',
'ski':'https://images.unsplash.com/photo-1454496522488-7a8e488e8606?auto=format&fit=crop&w=1200&q=85',
'snow':'https://images.unsplash.com/photo-1660830026772-f8eff2fcb610?auto=format&fit=crop&w=1400&q=85',
}
programs=[
('private','Индивидуальные уроки','Ваш темп. Ваш прогресс.','Всё внимание инструктора — вам. Разбираем движения, находим уверенность и работаем над тем, что важно именно сейчас.','Один на один','Первый выход на склон или работа над техникой','Персональный план занятия','Темп и сложность под ваш уровень'),
('group','Групповые уроки','Вместе получается больше.','Учиться легче, когда рядом люди с той же целью. Практика, поддержка и удовольствие от первых уверенных спусков.','В небольшой группе','Знакомство с лыжами и сноубордом','Группа по уровню подготовки','Упражнения и практика на склоне'),
('courses','Курсы','Не просто попробовать. Научиться.','Последовательная программа вместо отдельных занятий. От основ управления до более свободного и осознанного катания.','Серия занятий','Тем, кто хочет заниматься регулярно','Постепенное усложнение упражнений','Закрепление навыков между занятиями'),
('kids','Детские занятия','Большие открытия маленьких райдеров.','Знакомство со снегом через игру, движение и понятные задания. Помогаем ребёнку освоиться на склоне без спешки.','Для детей','Первое знакомство с горными лыжами','Игровой подход к обучению','Нагрузка с учётом возраста и опыта')]
nav=[('index','Главная')]+[(p[0],p[1]) for p in programs]
def link(slug): return slug+'.html'
def button(text,url,cls='button'):return f'<a class="{cls}" href="{url}">{text}</a>'
def header(slug):
 return '<header><a class="brand" href="index.html" aria-label="Almaty Snowboard — главная"><svg viewBox="0 0 50 36" aria-hidden="true"><path d="M3 33 23 3l24 30H3Z M14 17l9 6 7-10"/></svg><span class="brand-name">Almaty Snowboard<small>ЛЫЖИ И СНОУБОРД</small></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Меню <span>☰</span></button><nav id="navigation">'+''.join(f'<a href="{link(s)}" '+('aria-current="page"' if slug==s else '')+f'>{n}</a>' for s,n in nav)+'</nav>'+button('Подобрать занятие','contact.html','button header-cta')+'</header>'
def footer():return '<footer><a class="footer-brand" href="index.html">Almaty Snowboard</a><div><p>Горы становятся ближе,<br>когда чувствуешь уверенность.</p></div><div><a href="about.html">О школе</a><a href="contact.html">Подобрать занятие</a></div><small>Демонстрационная концепция. Школа, команда, тарифы и расписание вымышлены.<br>Фотографии иллюстративные. Сайт не принимает заявки и оплату.</small></footer>'
def cta(): return '<section class="cta"><div><p class="eyebrow">НАЧНЁМ С ВАШЕГО УРОВНЯ</p><h2>Первый спуск?<br>Или следующий шаг?</h2></div>'+button('Подобрать занятие','contact.html','button dark')+'</section>'
def cards():return '<div class="program-grid">'+''.join(f'<a class="program" href="{p[0]}.html"><span class="tag">{p[4]}</span><h3>{p[1]}</h3><p>{p[2]}</p><span class="card-link">О программе</span></a>' for p in programs)+'</div>'
home=f'''<section class="hero"><img class="hero-image" src="{photos['hero']}" alt="Заснеженный горный склон" fetchpriority="high"><div class="hero-content"><p class="eyebrow">ГОРНОЛЫЖНАЯ ШКОЛА</p><h1>Горы зовут.<br><em>Вы готовы.</em></h1><p class="lead">Горные лыжи и сноуборд.<br>От первого поворота до свободы на склоне.</p>{button('Выбрать обучение','#programs')}</div><div class="hero-bottom"><span>Лыжи / Сноуборд</span><span>С любого уровня подготовки</span></div></section>
<section class="section" id="programs"><div class="section-heading"><p class="eyebrow">ОБУЧЕНИЕ</p><h2>У каждого —<br>свой путь на склон.</h2><p>Начните с формата, который вам подходит.<br>Остальное разберём вместе.</p></div>{cards()}</section>
<section class="split"><div class="split-image"><img src="{photos['ski']}" loading="lazy" alt="Горный пейзаж со снежными вершинами"><span>МЕНЬШЕ СОМНЕНИЙ. БОЛЬШЕ КАТАНИЯ.</span></div><div class="split-copy"><p class="eyebrow">ПОДХОД К ОБУЧЕНИЮ</p><h2>Уверенность<br>начинается<br>с понимания.</h2><p>Не нужно быть спортивным героем, чтобы начать. Важно понять движения, почувствовать опору и двигаться в своём темпе.</p><div class="principle"><h3>Сначала — основы</h3><p>Экипировка, стойка, торможение и контроль скорости.</p></div><div class="principle"><h3>Затем — практика</h3><p>Понятные упражнения и обратная связь на склоне.</p></div>{button('Как мы учим','about.html','text-link')}</div></section>
<section class="section preparation"><p class="eyebrow">ПЕРЕД ПЕРВЫМ ЗАНЯТИЕМ</p><h2>Всё начинается<br>с простых вещей.</h2><div class="three"><article><h3>Выберите направление</h3><p>Лыжи или сноуборд — расскажите, что хочется попробовать и есть ли опыт катания.</p></article><article><h3>Подготовьте экипировку</h3><p>Шлем, маска, перчатки и одежда по погоде. Снаряжение должно подходить по размеру.</p></article><article><h3>Обсудите детали</h3><p>До выхода на склон уточните место встречи, длительность, стоимость и условия переноса.</p></article></div></section>{cta()}'''
def program(p):
 s,title,headline,desc,fmt,who,a,b=p
 return f'''<section class="page-hero"><p class="eyebrow">ОБУЧЕНИЕ / {title.upper()}</p><h1>{headline}</h1><p class="lead">{desc}</p>{button('Выбрать этот формат',f'contact.html?program={s}')}<div class="page-photo"><img src="{photos['hero' if s in ['private','kids'] else 'snow']}" alt="Зимние горы и снежный склон"></div></section><section class="section detail-layout"><div><p class="eyebrow">{fmt.upper()}</p><h2>На занятии<br>работаем над вашим<br>следующим шагом.</h2></div><div><article class="detail"><h3>Кому подойдёт</h3><p>{who}. Перед записью обсудим опыт и ожидания, чтобы подобрать подходящую программу.</p></article><article class="detail"><h3>Что в программе</h3><ul><li>{a}</li><li>{b}</li><li>Контроль скорости, повороты и безопасная остановка</li><li>Обратная связь и рекомендации для самостоятельной практики</li></ul></article><article class="detail"><h3>Что уточнить перед записью</h3><p>Дату, возраст участника, уровень катания и желаемую продолжительность. Стоимость, место встречи и доступность инструктора согласуются отдельно.</p></article></div></section><section class="section faq"><p class="eyebrow">ПОЛЕЗНО ЗНАТЬ</p><h2>До встречи на склоне.</h2><details><summary>Можно начать с нуля?</summary><p>Да. Укажите, что раньше не катались: знакомство с экипировкой и базовые движения должны быть частью первого занятия.</p></details><details><summary>Нужно ли своё снаряжение?</summary><p>Для занятия нужны исправные лыжи или сноуборд, ботинки и шлем. Возможность аренды и помощь с подбором уточняются при согласовании.</p></details><details><summary>Что делать при плохой погоде?</summary><p>Условия переноса необходимо согласовать до записи. При закрытии трасс или небезопасной погоде выход на склон откладывают.</p></details></section>{cta()}'''
about=f'''<section class="page-hero"><p class="eyebrow">О ШКОЛЕ</p><h1>Кататься.<br>Понимать.<br><em>Чувствовать горы.</em></h1><p class="lead">Школа для тех, кто хочет уверенно стоять на склоне и получать удовольствие от каждого спуска.</p><div class="page-photo"><img src="{photos['ski']}" alt="Горная вершина"></div></section><section class="section"><div class="section-heading"><p class="eyebrow">НАШ ПОДХОД</p><h2>Обучение без спешки.<br>Прогресс по существу.</h2></div><div class="three"><article><h3>Понятные объяснения</h3><p>Разбираем движения на простые действия. Важно понимать, что вы делаете и зачем.</p></article><article><h3>Подходящий уровень</h3><p>Учитываем опыт, физическую подготовку и цель. Задачи должны быть посильными.</p></article><article><h3>Внимание к безопасности</h3><p>Контроль скорости, дистанция и правила поведения на трассе — основа обучения.</p></article></div></section>{cta()}'''
contact='''<section class="section contact"><div><p class="eyebrow">ПОДБОР ЗАНЯТИЯ</p><h1>Ваш следующий<br>выход на склон.</h1><p class="lead">Несколько деталей помогут определиться<br>с форматом обучения.</p><p class="contact-note">Это предварительный подбор, без бронирования и оплаты. Контакты школы появятся после согласования с заказчиком.</p></div><form id="lesson-form"><label>Что хотите освоить?<select name="sport"><option>Горные лыжи</option><option>Сноуборд</option></select></label><label>Формат<select name="program"><option value="help">Помогите выбрать</option><option value="private">Индивидуальные уроки</option><option value="group">Групповые уроки</option><option value="courses">Курсы</option><option value="kids">Детские занятия</option></select></label><label>Уровень катания<select name="level"><option>Начинаю с нуля</option><option>Уже пробовал(а)</option><option>Уверенно катаюсь, хочу улучшить технику</option></select></label><label>Пожелания<textarea name="notes" rows="3" placeholder="Например: занятия для ребёнка, удобные даты"></textarea></label><button class="button" type="submit">Подобрать формат</button><p class="form-note">Данные остаются в браузере и никуда не отправляются.</p><div id="result" role="status" tabindex="-1" hidden></div></form></section>'''
from enrichment import enrich
home,about,contact,program=enrich(home,about,contact,program,cards,programs,photos,button)
pages={'index':('Горнолыжная школа',home),'about':('О школе',about),'contact':('Подобрать занятие',contact)}
for p in programs:pages[p[0]]=(p[1],program(p))
for slug,(title,body) in pages.items():
 (root/link(slug)).write_text(f'<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} — Almaty Snowboard</title><meta name="description" content="Горные лыжи и сноуборд: индивидуальные и групповые уроки, курсы, детские занятия. Подберите свой формат обучения."><meta name="theme-color" content="#141614"><link rel="stylesheet" href="style.css"><script src="app.js" defer></script></head><body class="{slug}"><a class="skip" href="#main">К содержимому</a>{header(slug)}<main id="main">{body}</main>{footer()}</body></html>',encoding='utf-8')
print('Generated',len(pages),'pages')

